def solution():
    # Define variables name and value
    actual_values = [
        150.2, 149.8, 150.5, 151.0, 150.7,
        151.5, 152.0, 151.8, 152.3, 152.1
    ]
    expected_values = [
        150.0, 150.1, 150.3, 150.9, 150.6,
        151.3, 152.1, 151.9, 152.5, 152.0
    ]

    # Calculate residuals
    residuals = [
        actual - expected
        for actual, expected in zip(actual_values, expected_values)
    ]

    # Calculate the Durbin-Watson statistic
    squared_sum = sum(residual ** 2 for residual in residuals)
    diff_squared_sum = sum(
        (residuals[i] - residuals[i - 1]) ** 2
        for i in range(1, len(residuals))
    )
    durbin_watson_statistic = diff_squared_sum / squared_sum

    # Return the answer rounded to two decimal places
    return round(durbin_watson_statistic, 2)
